L(OA3, 4,
  "Un espacio de 10 × 6 m, una pelota blanda, 4 conos, cintas de dos colores, un adulto que arbitre y zapatillas amarradas. Equipos de 3 y juego sin contacto.",
  "Aprenderé a usar la visión periférica: ver a los lados sin girar mucho la cabeza. Sirve para ver a mis compañeros y a los defensores mientras juego.",
  ["Sé acompañar la jugada.", "Sé que debo mirar el espacio libre."],
  ["La visión periférica es lo que ves a los lados de tu mirada mientras miras al frente. Si miras un punto, también ves, aunque con menos detalle, lo que hay a la derecha y a la izquierda. En un juego sirve para ver a tus compañeros y a los defensores sin dejar de mirar la pelota.",
   "Para practicarla, mira un punto al frente y, sin mover los ojos, trata de notar si algo se mueve a un lado. Por ejemplo, un compañero levanta un brazo a un costado y tú, mirando al frente, dices de qué lado fue. Si dices el lado correcto, tu visión periférica funcionó. A los lados notas bien el movimiento, pero no los detalles. La mirada tiene dos formas: enfocar un punto y abrir la atención a los lados.",
   "En el juego, antes de pasar, levanta la vista, mira a la pelota y luego a los lados. Después de pasar, vuelve a mirar el espacio. No camines de espaldas para ver mejor: gira la cabeza y el cuerpo con control. Esta práctica se hace sin correr rápido y sin contacto."],
  [("visión periférica", "lo que veo a los lados mientras miro al frente"), ("enfocar", "mirar un punto con atención"), ("atención abierta", "estar atento a todo lo que pasa alrededor"), ("levantar la vista", "mirar hacia adelante y no al suelo"), ("espacio", "lugar libre donde puedo moverme")],
  [("Probar la visión periférica", "Miras un punto al frente. Un compañero levanta un brazo a tu derecha, a un metro de tu cuerpo. Sin mover los ojos, ¿de qué lado notas el movimiento?", ["Miro el punto al frente.", "Noto algo que se mueve a un lado.", "El movimiento fue a mi derecha."], "A la derecha"),
   ("Antes de pasar", "Tienes la pelota y tu compañero está a tu izquierda. Un defensor está a tu derecha. ¿A quién ves antes de pasar?", ["Levanto la vista.", "Veo con visión periférica a ambos lados.", "Veo al compañero a la izquierda y al defensor a la derecha."], "A mi compañero y al defensor")],
  [("Mirar solo el suelo o la pelota.", "No ves a tus compañeros ni a los defensores.", "Levanta la vista y abre la atención a los lados."), ("Girar la cabeza muy rápido y perder el equilibrio.", "Te mareas o tropiezas.", "Gira con calma y mantén los pies firmes.")],
  [ex("Lo que ves a los lados mientras miras al frente, ¿es visión periférica o mirar solo el suelo?", "Visión periférica", "Es lo que se ve a los costados."),
   ex("Antes de pasar, ¿levantas la vista o miras el suelo?", "Levantas la vista", "Así ves a tus compañeros."),
   ex("¿Giras la cabeza con calma o muy rápido?", "Con calma", "Los giros bruscos hacen perder el equilibrio.")],
  [ex("Un compañero levanta un brazo a tu izquierda mientras miras al frente y dices «izquierda». ¿Funcionó tu visión periférica?", "Sí", "Notaste el movimiento y el lado sin mover los ojos."),
   ex("Pierdes la pelota porque solo mirabas el suelo. ¿Qué cambias: levantas la vista o corres más rápido?", "Levantas la vista", "Con la vista arriba ves las opciones."),
   ex("¿Por qué no conviene caminar de espaldas para mirar el juego?", "Porque puedes tropezar o chocar", "Caminar de espaldas es riesgoso.")],
  [arith("Haces 2 series de 3 intentos y en cada serie dices bien el lado 2 veces. ¿Cuántos aciertos tienes en total?", "2*2", "Se repiten 2 aciertos en cada una de las 2 series.", " aciertos"),
   arith("Haces 4 intentos y dices bien el lado 3 veces. ¿Cuántas veces te equivocaste?", "4-3", "Se restan los aciertos de los intentos.", " vez"),
   arith("Juegas 5 jugadas y en cada una miras a los lados 2 veces. ¿Cuántas veces miraste a los lados?", "5*2", "Se repiten 2 miradas cinco veces.", " veces")],
  [ex("Leo miró la pelota y vio a su compañero libre a la izquierda. Mía miró solo el suelo y no vio a nadie. ¿Quién usó mejor la visión periférica?", "Leo", "Vio a su compañero sin dejar de mirar la pelota."),
   ex("Toño dice: «Para ver todo hay que girar la cabeza al máximo en cada paso». ¿Es correcto?", "No", "Se puede ver bastante con la visión periférica sin girar tanto.")],
  [ex("Corres con la pelota y no ves que un compañero viene por el costado. ¿Qué haces: A) sigues sin mirar, B) levantas la vista y miras a los lados con calma?", "B", "Levantar la vista evita choques y da opciones de pase.")],
  [ex("¿Qué es la visión periférica?", "Lo que veo a los lados mientras miro al frente", "Es la visión de los costados."),
   ex("¿Dónde miras antes de pasar: al suelo o a los lados?", "A los lados", "Así ves a los compañeros."),
   arith("Ves a 2 compañeros a la izquierda y 1 a la derecha. ¿Cuántos compañeros ves?", "2+1", "Se suman los de ambos lados.", " compañeros")],
  ("Con un compañero a cada lado, miren un punto al frente. Un adulto o compañero levanta un brazo a la derecha o a la izquierda, sin avisar. Tú dices «derecha» o «izquierda» sin mover los ojos. Hagan 6 intentos y anoten cuántos acertaste. Después jueguen 3 pases en tríos mirando la pelota y diciendo dónde está cada compañero.",
   "Acerté 4 de 6 intentos de lado. En el juego, dije «uno a la izquierda y otro a la derecha» antes de pasar y no se me cayó la pelota.",
   ["usa la visión periférica sin mover los ojos", "levanta la vista antes de pasar", "gira la cabeza con calma"],
   ["tabla de intentos", "observación de un adulto", "relato oral"],
   ["mirar solo el suelo", "girar la cabeza con brusquedad", "caminar de espaldas"],
   "Reconoce los aciertos y pide más práctica en el lado con menos aciertos."),
  "Mira un punto al frente y di de qué lado levanta el brazo un compañero.",
  "Repite el ejercicio del brazo levantado mientras caminas despacio en círculo con tu compañero.")

# ---------------------------------------------------------------- OA 04
L(OA4, 1,
  "Una plaza, parque o patio cercano al que puedas ir con una persona adulta, papel, lápiz y zapatillas cómodas. Si no puedes salir, usa el patio o la cuadra y la lista de riesgos de esta clase.",
  "Aprenderé a leer un lugar al aire libre: qué juegos permite y qué riesgos tiene. Sirve para elegir dónde y cómo jugar con seguridad.",
  ["Sé reconocer lugares seguros para jugar.", "Sé que debo avisar a un adulto cuando salgo."],
  ["El entorno es el lugar donde haces actividad física: una plaza, una playa, un parque, un sendero o una calle tranquila. Cada entorno ofrece oportunidades distintas. En una plaza activa hay juegos y espacio para correr. En una playa, arena para caminar o jugar. En un sendero natural, un camino para caminar. En un parque, pistas para andar en bicicleta.",
   "Cada entorno también tiene riesgos. En la plaza pueden estar los juegos rotos o hay mucha gente. En la playa hay sol fuerte, olas y arena caliente. En un sendero, el suelo puede ser disparejo o con piedras. En una calle hay autos. Antes de jugar, mira alrededor y detecta oportunidades y riesgos. Esto se llama leer el entorno.",
   "Si encuentras un riesgo, tienes tres opciones: elegir otro lugar, cambiar el juego o avisar a un adulto. Nunca juegues en lugares con autos en movimiento, cerca del agua sin un adulto, ni en juegos rotos. Una actividad al aire libre se hace siempre con una persona adulta que sepa dónde estás."],
  [("entorno", "el lugar donde hago actividad física"), ("plaza activa", "plaza con espacio y juegos para moverse"), ("sendero", "camino angosto para caminar"), ("oportunidad", "algo que me permite jugar o moverme bien"), ("riesgo", "algo que puede hacerme daño")],
  [("Leer una plaza", "En una plaza ves un espacio de pasto parejo, un columpio con la cadena rota y un camino pavimentado. ¿Qué es una oportunidad y qué es un riesgo?", ["El pasto parejo permite correr: es una oportunidad.", "El columpio roto puede lastimar: es un riesgo.", "El camino pavimentado permite caminar o andar en bicicleta."], "Oportunidades: pasto y camino; riesgo: columpio roto"),
   ("Elegir qué hacer", "Quieres jugar a la pelota, pero la cancha de la plaza está llena de pequeños y hay una calle con autos justo al lado. ¿Qué haces?", ["Hay gente y autos cerca.", "Es mejor cambiar el juego o el lugar.", "Aviso a la persona adulta y elijo un lugar más tranquilo."], "Cambio de lugar o de juego y aviso al adulto")],
  [("Pensar que todos los lugares son seguros.", "Los juegos rotos, los autos o el agua son riesgos reales.", "Mira alrededor antes de jugar."), ("Salir a jugar sin avisar.", "Nadie sabe dónde estás si necesitas ayuda.", "Avisa siempre a una persona adulta.")],
  [ex("Una plaza con pasto parejo permite correr. ¿Eso es una oportunidad o un riesgo?", "Una oportunidad", "Permite moverse bien."),
   ex("Un columpio con la cadena rota, ¿es una oportunidad o un riesgo?", "Un riesgo", "Puede lastimarte seriamente."),
   ex("Antes de salir a jugar, ¿avisas a un adulto o sales sin avisar?", "Avisas a un adulto", "Debe saber dónde estás.")],
  [ex("En una playa hay sol fuerte y olas. ¿Qué es más seguro: A) jugar solo cerca del agua, B) jugar en la arena seca con un adulto?", "B", "Un adulto y distancia del agua cuidan tu seguridad."),
   ex("Un sendero tiene piedras sueltas. ¿Qué haces: caminas con cuidado o corres rápido?", "Caminas con cuidado", "Las piedras sueltas hacen resbalar."),
   ex("En una calle con autos en movimiento, ¿se puede jugar a la pelota?", "No", "Los autos son un riesgo grave.")],
  [arith("En la plaza ves 4 oportunidades y 3 riesgos. ¿Cuántas cosas anotaste en total?", "4+3", "Se suman oportunidades y riesgos.", " cosas"),
   arith("Hay 6 juegos en la plaza y 2 están rotos. ¿Cuántos juegos puedes usar?", "6-2", "Se restan los rotos de los totales.", " juegos"),
   arith("Recorres 3 lugares y en cada uno anotas 2 riesgos. ¿Cuántos riesgos anotaste?", "3*2", "Se repiten 2 riesgos tres veces.", " riesgos")],
  [ex("Pía revisó que no hubiera juegos rotos ni autos y avisó a su adulto. Rodo corrió directo al columpio sin mirar. ¿Quién leyó mejor el entorno?", "Pía", "Revisó los riesgos antes de jugar."),
   ex("Gina dice: «Si es un parque, no hay riesgos». ¿Es correcto?", "No", "Cualquier lugar puede tener riesgos.")],
  [ex("Quieres andar en bicicleta por un camino que cruza una calle con autos. ¿Qué haces: A) cruzas rápido, B) esperas a un adulto y buscas otro camino o cruzas de la mano con él?", "B", "Cruzar calles con un adulto reduce el riesgo.")],
  [ex("¿Cómo se llama el lugar donde hago actividad física?", "Entorno", "Es mi entorno."),
   ex("¿Qué haces si encuentras un riesgo: lo ignoras o eliges otro lugar?", "Eliges otro lugar", "Evitar el riesgo es lo correcto."),
   arith("Hay 5 riesgos y ya resolviste 3. ¿Cuántos faltan?", "5-3", "Se restan los resueltos de los totales.", " riesgos")],
  ("Con una persona adulta, recorre una plaza, parque o patio cercano. Anota 3 oportunidades (por ejemplo, un camino o un espacio de pasto) y 3 riesgos (por ejemplo, un juego roto o una calle cercana). Elige un juego seguro para ese lugar. Si no puedes salir, imagina el patio de tu casa y haz la misma lista.",
   "Oportunidades: pasto parejo, camino y sombra. Riesgos: columpio roto, calle cercana y agua en el suelo. Elegí jugar a la pelota lejos de la calle.",
   ["anota oportunidades y riesgos reales", "elige un juego seguro", "avisa a un adulto"],
   ["lista escrita", "observación de un adulto", "relato oral"],
   ["no ver riesgos", "salir sin avisar", "jugar cerca de autos"],
   "Reconoce un riesgo bien detectado y pide un riesgo nuevo para la próxima vez."),
  "Dibuja un lugar seguro para jugar con 2 oportunidades y 2 riesgos marcados.",
  "Compara dos lugares (plaza y patio) y anota cuál tiene más oportunidades y cuál tiene más riesgos.")

L(OA4, 2,
  "Una mochila, una botella de agua, un sombrero o gorro, ropa cómoda, zapatillas amarradas, papel y lápiz. Una persona adulta que acompañe. Si vas en bicicleta, un casco bien ajustado.",
  "Aprenderé a preparar una actividad al aire libre: qué llevar y qué hacer antes de salir. Sirve para salir a pasear o jugar con seguridad.",
  ["Sé reconocer riesgos en un entorno.", "Sé que debo avisar a un adulto cuando salgo."],
  ["Antes de una actividad al aire libre, prepárate. Primero, avisa a una persona adulta adónde vas, con quién y a qué hora volverás. Segundo, lleva lo necesario: agua para beber, un sombrero o gorro, protector solar según indique un adulto, ropa cómoda y zapatillas bien amarradas. Tercero, revisa el clima: si hay mucho calor, lluvia fuerte o viento, cambia el plan.",
   "Si vas a andar en bicicleta, usa casco bien ajustado, anda solo por lugares permitidos y con un adulto. No lleves objetos sueltos que cuelguen. Si vas a la playa, ve con un adulto y no te acerques al agua sin permiso. En un sendero, usa calzado cerrado y camina por el camino marcado. Lleva una bolsa para la basura que generes.",
   "Una buena lista ayuda a no olvidar nada. Por ejemplo: agua, gorro, bolsa de basura, colación saludable, avisar, ropa cómoda. Antes de salir, revisa cada cosa. Así reduces riesgos y cuidas el lugar. Si falta algo importante, como el agua o el aviso a un adulto, no sales hasta resolverlo."],
  [("preparar", "dejar listo lo necesario antes de una actividad"), ("hidratarse", "beber agua para reponer la que pierde el cuerpo"), ("casco", "protección rígida para la cabeza al andar en bicicleta"), ("lista", "papel con las cosas que no debo olvidar"), ("clima", "calor, frío, lluvia o viento del día")],
  [("Armar la lista", "Vas a una caminata de 2 horas. Ya tienes agua, gorro y bolsa para basura. Te faltan avisar y la colación. ¿Cuántas cosas tienes listas y cuántas faltan?", ["Listas: agua, gorro, bolsa. Son 3.", "Faltan: avisar y colación. Son 2.", "3 listas y 2 por resolver."], "3 listas y 2 faltan"),
   ("Revisar el clima", "El día está con mucho calor y sol fuerte a mediodía. Quieres caminar por un sendero sin sombra. ¿Qué cambias?", ["El sol fuerte hace daño y cansa.", "Puedo salir más temprano o más tarde.", "Llevo agua, gorro y busco sombra."], "Cambiar el horario y llevar agua y gorro")],
  [("Salir sin agua porque «es un paseo corto».", "El cuerpo pierde líquido incluso en paseos cortos.", "Lleva siempre agua."), ("Andar en bicicleta sin casco.", "Una caída puede dañar la cabeza.", "Usa casco bien ajustado, siempre.")],
  [ex("¿Qué llevas para beber en una caminata: agua o una bebida muy dulce?", "Agua", "El agua hidrata mejor."),
   ex("Para andar en bicicleta, ¿usas casco o no es necesario?", "Usas casco", "Protege la cabeza."),
   ex("¿Avisas a un adulto antes de salir o te vas sin avisar?", "Avisas", "Debe saber dónde estarás.")],
  [ex("Una lista tiene: agua, gorro, colación y ropa cómoda. ¿Qué paso importante antes de salir no está en la lista: avisar a un adulto o llevar un balón?", "Avisar a un adulto", "El aviso es parte de la preparación; el balón no es necesario."),
   ex("Si el día está lloviendo fuerte, ¿sigues con el sendero o cambias el plan?", "Cambias el plan", "El clima fuerte aumenta el riesgo."),
   ex("¿Para qué llevas una bolsa de basura?", "Para no dejar basura en el lugar", "Cuidas el entorno.")],
  [arith("Tu lista tiene 8 cosas y ya tienes 5. ¿Cuántas faltan?", "8-5", "Se restan las que tienes de las que necesitas.", " cosas"),
   arith("Caminarás 2 horas y una persona adulta te pide tomar agua cada 30 minutos. ¿Cuántas pausas de agua harás?", "120//30", "Dos horas son 120 minutos y se divide por 30.", " pausas"),
   arith("Salen 3 niños y 1 adulto, y cada persona lleva 1 colación. ¿Cuántas colaciones hay en total?", "3+1", "Se suman las colaciones de los niños y la del adulto.", " colaciones")],
  [ex("Ema revisó su lista, avisó y llevó agua. Tito salió sin agua ni aviso. ¿Quién preparó mejor la actividad?", "Ema", "Hizo todo lo necesario."),
   ex("Olga dice: «Con el celular basta, no necesito avisar». ¿Es correcto?", "No", "Un adulto debe saber adónde vas.")],
  [ex("Vas a andar en bicicleta y el casco está roto. ¿Qué haces: A) lo usas igual, B) pides uno en buen estado a un adulto o no sales?", "B", "Un casco roto no protege.")],
  [ex("¿Qué llevas para hidratarte?", "Agua", "Es lo básico."),
   ex("¿Qué haces antes de salir: avisar o irte?", "Avisar", "Un adulto debe saber."),
   arith("Llevas 2 botellas de agua y bebes 1. ¿Cuántas te quedan?", "2-1", "Se restan las que bebiste.", " botella")],
  ("Prepara una salida imaginaria de 2 horas a una plaza o sendero. Escribe una lista de 6 cosas que llevarías (incluye agua, gorro, aviso a un adulto y una bolsa para basura), cuántas pausas de agua harías si tomas agua cada 30 minutos y qué harías si el día amanece con lluvia fuerte.",
   "Lista: agua, gorro, bolsa de basura, colación, ropa cómoda, aviso a un adulto. Haría 4 pausas de agua. Si llueve fuerte, cambio el plan y juego bajo techo.",
   ["incluye lo esencial", "calcula el agua", "cambia el plan con mal clima"],
   ["lista escrita", "dibujo de la mochila", "relato oral"],
   ["olvidar el aviso", "salir sin agua", "no revisar el clima"],
   "Reconoce los elementos completos de la lista y pide revisar el clima."),
  "Haz una lista de 4 cosas para llevar a una plaza.",
  "Arma la mochila para un paseo en bicicleta y agrega el casco.")

L(OA4, 3,
  "Una bolsa de basura, guantes de jardín si los hay (sin tocar vidrio ni objetos cortantes), una plaza, parque o patio y una persona adulta. Si no puedes salir, usa el patio de tu casa.",
  "Aprenderé a moverme sin dejar basura ni dañar plantas ni animales. Sirve para que los lugares queden limpios para todos.",
  ["Sé preparar una actividad al aire libre.", "Sé que la basura va en un basurero."],
  ["Cuidar el entorno es dejarlo igual o mejor que como lo encontraste. Para eso hay medidas simples. Primera: llévate tu basura, incluso las cáscaras y los papeles pequeños. Segunda: camina por los caminos marcados y no pises plantas. Tercera: no rompas ramas ni arranques flores. Cuarta: respeta a los animales y no los persigas.",
   "Esto se llama mínimo impacto: dejar la menor huella posible. En una plaza, usa los basureros o llévate la basura a casa si no hay. En una playa, no dejes bolsas ni botellas. En un sendero, no te salgas del camino para no pisar plantas. Si ves basura de otros, avisa a un adulto; no la toques si es vidrio, cortante o sucia.",
   "Moverse sin dejar rastro también es jugar con cuidado. Si juegas a la pelota, evita que caiga en jardines. Si andas en bicicleta, no frenes de golpe sobre el pasto. Cuidar el entorno es una forma de cuidar a las demás personas que lo usarán. Hazlo siempre, aunque nadie te mire."],
  [("mínimo impacto", "dejar la menor huella posible en el lugar"), ("residuo", "basura que queda después de usar algo"), ("conservar", "cuidar para que el lugar siga bien"), ("camino marcado", "ruta hecha para caminar"), ("respetar", "cuidar a personas, animales y plantas")],
  [("Qué hacer con la basura", "Terminas un jugo y tienes la caja vacía. En la plaza no hay basurero. ¿Qué haces?", ["Quiero dejar el lugar limpio.", "No la dejo en el suelo.", "La guardo en la bolsa y la llevo a casa."], "Guardarla y llevarla a casa"),
   ("Cuidar las plantas", "Caminas por un sendero y hay un atajo que pasa sobre pasto con flores. ¿Qué haces?", ["Las flores se dañarían.", "El camino marcado es mejor.", "Sigo por el camino marcado."], "Seguir por el camino marcado")],
  [("Dejar un papel pequeño porque «no se nota».", "Muchos papeles pequeños ensucian el lugar.", "Guarda todo en tu bolsa."), ("Tomar vidrio roto del suelo con la mano.", "Puedes cortarte.", "Avisa a un adulto sin tocarlo.")],
  [ex("Si no hay basurero, ¿dejas la basura en el suelo o te la llevas?", "Te la llevas", "Así el lugar queda limpio."),
   ex("Caminar por el camino marcado, ¿cuida las plantas o las daña?", "Las cuida", "No se pisan las plantas."),
   ex("Si ves vidrio roto en el suelo, ¿lo tomas con la mano o avisas a un adulto?", "Avisas a un adulto", "El vidrio puede cortar.")],
  [ex("Dejar la menor huella posible se llama mínimo impacto. ¿Es mínimo impacto dejar una botella en la arena?", "No", "La botella ensucia la playa."),
   ex("Tu pelota cae a un jardín con flores. ¿Entras corriendo o pides ayuda a un adulto?", "Pides ayuda a un adulto", "Así no dañas las flores."),
   ex("¿Por qué es mejor no perseguir a los animales?", "Para no asustarlos ni lastimarlos", "Los animales viven en ese lugar y deben estar tranquilos.")],
  [arith("Recoges 4 papeles propios y 3 papeles que dejó el viento. ¿Cuántos papeles guardas en tu bolsa?", "4+3", "Se suman los papeles de ambos tipos.", " papeles"),
   arith("Cada niño del grupo lleva 2 bolsas y son 5 niños. ¿Cuántas bolsas hay?", "5*2", "Se repite 2 bolsas cinco veces.", " bolsas"),
   arith("Llevas 6 envases y botas 4 en el basurero. ¿Cuántos te llevas a casa?", "6-4", "Se restan los que botaste en el basurero.", " envases")],
  [ex("Dani dejó su bolsa en el suelo. Paula la guardó en su mochila. ¿Quién aplicó el mínimo impacto?", "Paula", "Se llevó su basura."),
   ex("Leo dice: «Si nadie me ve, puedo dejar la basura». ¿Es correcto?", "No", "El cuidado no depende de que alguien mire.")],
  [ex("Tu grupo termina de jugar y hay una bolsa llena de basura en la banca que no es de ustedes. ¿Qué hacen: A) la dejan, B) avisan a un adulto para que la boten bien?", "B", "Avisar a un adulto permite resolver sin riesgo.")],
  [ex("¿Qué haces con tu basura si no hay basurero?", "Te la llevas", "Así no ensucias."),
   ex("¿Por dónde caminas en un sendero?", "Por el camino marcado", "Así cuidas las plantas."),
   arith("Había 7 papeles y recogiste 5. ¿Cuántos quedan en el suelo?", "7-5", "Se restan los recogidos de los que había.", " papeles")],
  ("Con un adulto, juega 15 minutos en una plaza o patio. Al terminar, haz una ronda de limpieza: junta los residuos que sean tuyos o seguros (papeles, envases de plástico) en una bolsa, sin tocar vidrio ni objetos cortantes. Anota cuántos juntaste y qué hiciste con ellos. Si no puedes salir, hazlo en el patio de tu casa.",
   "Junté 7 papeles y 3 envases de plástico, 10 en total. Los guardé en la bolsa y los botamos en la casa. No toqué el vidrio y avisé al adulto.",
   ["junta solo residuos seguros", "usa la bolsa y bota bien", "avisa al adulto sobre lo peligroso"],
   ["conteo de residuos", "foto o dibujo del lugar limpio", "relato oral"],
   ["dejar basura", "tocar vidrio", "salir del camino"],
   "Reconoce el cuidado del lugar y pide revisar mejor el rincón menos visible."),
  "Junta 5 residuos seguros en una bolsa y cuéntalos.",
  "Haz un afiche con 3 reglas de mínimo impacto para una plaza.")

L(OA4, 4,
  "Un patio o plaza, una persona adulta, papel, lápiz y zapatillas con buen agarre. Si hay lluvia, solo se hace en un lugar techado. No se practica en suelo mojado resbaloso.",
  "Aprenderé a ajustar mi actividad cuando cambian el clima o la superficie. Sirve para jugar seguro con calor, viento, lluvia o suelo disparejo.",
  ["Sé preparar una actividad al aire libre.", "Sé reconocer riesgos en el entorno."],
  ["El clima y la superficie pueden cambiar tu actividad. Con mucho calor, juega en la sombra, bebe agua y baja la intensidad. Con viento fuerte, evita lanzar objetos livianos y busca un lugar protegido. Con lluvia, suspende la actividad o hazla en un lugar techado, porque el suelo mojado resbala. Si hay truenos, entra a un lugar cerrado.",
   "La superficie también importa. En arena, correr cansa más y conviene ir más lento. En pasto húmedo se resbala, así que camina. En un sendero con piedras, camina con cuidado. En cemento, evita saltos altos porque el golpe es más duro. Antes de empezar, prueba la superficie con un paso lento.",
   "Ajustar significa elegir el cambio más seguro que mantenga la actividad: acortar el tiempo, bajar la velocidad, cambiar de lugar o cambiar de juego. Por ejemplo, si hace calor intenso, camina en lugar de correr o juega más temprano. Si el suelo está mojado, cambia a un juego de mesa o de pies firmes bajo techo. Pregunta a un adulto antes de seguir."],
  [("superficie", "el suelo donde me muevo: arena, pasto, cemento"), ("ajustar", "cambiar algo para que sea más seguro"), ("suspender", "detener la actividad para otro momento"), ("resbalar", "perder el agarre del pie en el suelo"), ("intensidad", "qué tan fuerte me muevo")],
  [("Calor intenso", "Hace mucho calor a las 3 de la tarde y quieres correr en un patio sin sombra. ¿Qué ajustas?", ["Hace mucho calor.", "Puedo cambiar de lugar o de hora.", "Camino a la sombra y bebo agua, o espero a que baje el calor."], "Cambiar a la sombra o a otra hora"),
   ("Suelo mojado", "Llovió y el patio tiene baldosas mojadas. Quieres jugar a las carreras. ¿Qué haces?", ["Las baldosas mojadas resbalan.", "Una carrera puede terminar en caída.", "Cambio a un juego bajo techo con pies firmes."], "Cambiar a un juego bajo techo")],
  [("Correr en baldosas mojadas.", "Se resbala fácil y puede haber caídas.", "Suspende la carrera o cambia de lugar."), ("Seguir jugando cuando hay truenos.", "Es peligroso estar al aire libre.", "Entra a un lugar cerrado y avisa al adulto.")],
  [ex("En un día de mucho calor, ¿buscas la sombra o corres bajo el sol sin parar?", "Buscas la sombra", "La sombra reduce el calor."),
   ex("En pasto mojado, ¿caminas o corres rápido?", "Caminas", "El pasto mojado resbala."),
   ex("Si hay truenos, ¿sigues jugando afuera o entras a un lugar cerrado?", "Entras a un lugar cerrado", "Los truenos son una señal de peligro.")],
  [ex("Corres en arena y te cansas rápido. ¿Es normal que cueste más en arena que en cemento?", "Sí", "La arena se hunde y exige más esfuerzo."),
   ex("El viento es muy fuerte y quieres lanzar una pelota liviana. ¿Cambias de lugar o lanzas igual?", "Cambias de lugar", "El viento desvía la pelota y puede llevarla a un riesgo."),
   ex("Para saber si un suelo resbala, ¿das un paso lento y pruebas o corres para ver?", "Das un paso lento y pruebas", "Probar despacio evita caídas.")],
  [arith("Hacías 3 carreras de 20 segundos y con calor las reduces a 1 carrera de 20 segundos. ¿Cuántos segundos menos corres?", "3*20-1*20", "Se calcula el tiempo antes y después y se restan.", " segundos"),
   arith("Un adulto te recuerda tomar agua cada 15 minutos mientras juegan 60 minutos. ¿Cuántos recordatorios hace?", "60//15", "Se divide el tiempo total por 15 minutos.", " recordatorios"),
   arith("Hay 4 señales de riesgo en el clima y ya revisaste 3. ¿Cuántas faltan?", "4-3", "Se restan las revisadas de las totales.", " señal")],
  [ex("Mari suspendió la carrera al ver el piso mojado. Teo corrió igual y se resbaló. ¿Quién ajustó la actividad?", "Mari", "Tomó la decisión más segura."),
   ex("Rita dice: «Si llueve un poco, no importa el suelo». ¿Es correcto?", "No", "Un poco de lluvia ya vuelve el suelo resbaloso.")],
  [ex("Estás jugando en la plaza cuando empiezan los truenos. ¿Qué haces: A) terminas el partido, B) avisas al adulto y entran a un lugar cerrado?", "B", "Los truenos indican peligro.")],
  [ex("¿Qué haces con mucho calor: buscas sombra o corres sin parar?", "Buscas sombra", "Cuidas tu cuerpo."),
   ex("¿Qué superficie resbala: la mojada o la seca?", "La mojada", "El agua quita agarre."),
   arith("Juegas 20 minutos bajo el sol y 10 en la sombra. ¿Cuántos minutos son en total?", "20+10", "Se suman los dos tiempos.", " minutos")],
  ("Imagina estos tres días: uno con calor intenso, uno con lluvia fuerte y uno con viento fuerte. Para cada día escribe qué ajustes harías (lugar, hora o juego) para mantener una actividad segura. Revisa tus ajustes con una persona adulta.",
   "Calor: juego en la sombra y bebo agua, en la mañana. Lluvia: juego bajo techo con pies firmes. Viento: dejo la pelota liviana y juego a las escondidas en el patio.",
   ["propone un ajuste para cada clima", "prioriza la seguridad", "consulta a un adulto"],
   ["tabla de tres días", "relato oral", "dibujo"],
   ["ignorar el clima", "jugar en suelo mojado", "no consultar"],
   "Reconoce los ajustes y pide aclarar el lugar y el horario."),
  "Elige un ajuste para un día de calor intenso y escríbelo.",
  "Compara cómo cambia una carrera en arena, pasto seco y cemento.")

L(OA4, 5,
  "Un cuaderno o papel, lápiz, una plaza o patio recorrido en esta unidad, una bolsa y una persona adulta. Si no puedes salir, usa tus anotaciones de las clases anteriores.",
  "Aprenderé a evaluar si cuidé el lugar donde jugué. Sirve para mejorar la próxima vez.",
  ["Sé cuidar el entorno.", "Sé ajustar una actividad al clima."],
  ["Evaluar es revisar lo que hiciste y decidir cómo mejorar. Para evaluar el cuidado de un espacio, usa una lista de verificación con preguntas simples: ¿recogí mi basura?, ¿caminé por el camino marcado?, ¿cuidé las plantas y los animales?, ¿dejé el lugar limpio?, ¿avisé a un adulto? Cada pregunta se responde con sí o no. Si una pregunta no se aplica al lugar, por ejemplo porque no había camino marcado, cuéntala como sí.",
   "Si respondes sí a 4 o 5 preguntas, el cuidado fue muy bueno. Si respondes sí a 2 o 3, fue regular y debes mejorar algo. Si respondes sí a 0 o 1, hay que cambiar varias cosas la próxima vez. Esta lista no es para castigar, sino para aprender. También mira qué no resultó: ¿se acabó el agua?, ¿faltó la bolsa?",
   "Elige una mejora concreta para la próxima salida, por ejemplo: «llevaré una bolsa más grande» o «saldré con más tiempo». Pide a un adulto que lea tu lista y te dé una idea. Cuando cuidas los lugares, todos pueden jugar y descansar en ellos después de ti."],
  [("evaluar", "revisar lo que hice y decidir cómo mejorar"), ("lista de verificación", "preguntas de sí o no para revisar algo"), ("mejora", "cambio que voy a hacer para que salga mejor"), ("huella", "marca que dejo en un lugar"), ("cuidado", "atención para no dañar algo")],
  [("Contar los sí", "En tu lista de 5 preguntas respondes sí a 4. ¿Cómo fue el cuidado?", ["Cuento los sí: 4.", "4 o 5 es muy bueno.", "El cuidado fue muy bueno."], "Muy bueno"),
   ("Elegir una mejora", "Respondiste no a «¿dejé el lugar limpio?» porque no tenías bolsa. ¿Cuál es una buena mejora?", ["El problema fue la falta de bolsa.", "Puedo llevar una bolsa extra.", "Lo agrego a mi lista de salida."], "Llevar una bolsa extra")],
  [("Evaluar solo lo que salió mal.", "Pierdes de vista lo que ya haces bien.", "Anota lo que salió bien y lo que mejorarás."), ("No hacer ninguna mejora.", "Sin cambios, el problema se repite.", "Elige un cambio concreto.")],
  [ex("En tu plaza no había camino marcado. Según la clase, ¿la pregunta «¿caminé por el camino marcado?» la cuentas como sí o como no?", "Como sí", "Si una pregunta no se aplica al lugar, se cuenta como sí."),
   ex("Si respondes sí a 5 de 5 preguntas, ¿el cuidado fue muy bueno o regular?", "Muy bueno", "Cumpliste todas las medidas."),
   ex("Al evaluar, ¿anotas solo lo malo o también lo bueno?", "También lo bueno", "Ambos ayudan a mejorar.")],
  [ex("Respondes sí a 2 de 5 preguntas. ¿El cuidado fue muy bueno o regular?", "Regular", "2 o 3 sí es regular."),
   ex("Tu mejora es «llevar una bolsa extra». ¿Es concreta o muy general?", "Concreta", "Dice qué cambiar."),
   ex("¿Para qué sirve la lista de verificación: castigar o aprender?", "Aprender", "Ayuda a mejorar.")],
  [arith("De 5 preguntas respondes sí a 4. ¿A cuántas respondiste no?", "5-4", "Se restan los sí de las preguntas.", " pregunta"),
   arith("Hiciste 3 salidas y en cada una anotaste 5 preguntas. ¿Cuántas preguntas respondiste en total?", "3*5", "Se repiten 5 preguntas tres veces.", " preguntas"),
   arith("En la primera salida tuviste 2 sí, en la segunda 3 y en la tercera 4. ¿Cuántos sí sumaste?", "2+3+4", "Se suman los sí de las tres salidas.", " sí")],
  [ex("Fer tuvo 4 sí en su primera salida y 5 en la segunda. ¿Mejoró?", "Sí", "Pasó de 4 a 5."),
   ex("Pablo dice: «Si saqué 3 sí, no puedo mejorar». ¿Es correcto?", "No", "Puede subir con una mejora concreta.")],
  [ex("Al evaluar, ves que dejaste una botella en el parque. ¿Qué haces: A) la dejas, B) vuelves con un adulto y la recoges?", "B", "Arreglar el problema es parte de cuidar el espacio.")],
  [ex("¿Qué es evaluar?", "Revisar lo que hice y decidir cómo mejorar", "Es mirar lo hecho."),
   ex("¿Sí a 5 de 5 es muy bueno o regular?", "Muy bueno", "Cumpliste todas las medidas."),
   arith("Respondes 3 sí y 2 no. ¿Cuántas preguntas había?", "3+2", "Se suman los sí y los no.", " preguntas")],
  ("Usa esta lista de verificación para evaluar una salida o un juego en el patio: 1) ¿Recogí mi basura? 2) ¿Caminé por el camino marcado? 3) ¿Cuidé las plantas y los animales? 4) ¿Dejé el lugar limpio? 5) ¿Avisé a un adulto? Responde sí o no a cada una, cuenta los sí y elige una mejora concreta para la próxima vez.",
   "Respondí sí a 4 de 5. No avisé porque olvidé. Mejora: pegaré una nota en la puerta que diga «avisar».",
   ["responde con honestidad", "cuenta los sí", "elige una mejora concreta"],
   ["lista respondida", "relato oral", "observación de un adulto"],
   ["no ser honesto", "no elegir mejora", "culpar a otros"],
   "Reconoce la honestidad al responder y pide que la mejora sea concreta y fácil."),
  "Responde la lista de verificación de 5 preguntas sobre tu último juego al aire libre.",
  "Compara dos listas de dos salidas y explica qué mejoró.")
